body = _json.get("body", {})
jwt = _json.get("jwt", {})

text = (body.get("guidelines_text") or "").strip()
brand_kit_id = body.get("brand_kit_id") or ""
org_id = jwt.get("org_id") or ""

MAX_CHARS = 220
OVERLAP_SENTENCES = 1

def split_sentences(block):
    out, buf = [], ""
    for ch in block:
        buf += ch
        if ch in ".!?" and len(buf.strip()) > 20:
            out.append(buf.strip())
            buf = ""
    if buf.strip():
        out.append(buf.strip())
    return out

chunks = []
if text:
    for para in [p.strip() for p in text.split("\n") if p.strip()]:
        sentences = split_sentences(para)
        current = []
        for s in sentences:
            candidate = " ".join(current + [s])
            if len(candidate) > MAX_CHARS and current:
                chunks.append(" ".join(current))
                current = current[-OVERLAP_SENTENCES:] + [s]
            else:
                current.append(s)
        if current:
            chunks.append(" ".join(current))

chunks = [c for c in chunks if len(c) > 30]

return [{
    "json": {
        "org_id": org_id,
        "brand_kit_id": brand_kit_id,
        "chunk_count": len(chunks),
        "chunks": chunks,
        "batch_body": {
            "requests": [
                {
                    "model": "models/gemini-embedding-001",
                    "content": {"parts": [{"text": c}]},
                    "outputDimensionality": 128,
                }
                for c in chunks
            ]
        },
    }
}]

"""
Pair each chunk with its embedding.

The HTTP Request node replaces $json entirely, so the chunk text is no longer
in scope. _node._node_results holds every node's output, which is how we
recover it. The probe below records what was found so a failure is diagnosable
rather than silent.
"""

resp = _json.get("body", {})
embeddings = [e.get("values", []) for e in resp.get("embeddings", [])]

chunks, org_id, brand_kit_id = [], "", ""
probe = "not-attempted"

try:
    results = _node._node_results
    probe = "keys=" + str(list(results.keys()))[:200]

    for _, payload in results.items():
        items = payload if isinstance(payload, list) else payload.get("items", [])
        for item in items:
            j = item.get("json", {}) if isinstance(item, dict) else {}
            if "chunks" in j and isinstance(j["chunks"], list):
                chunks = j["chunks"]
                org_id = j.get("org_id", "")
                brand_kit_id = j.get("brand_kit_id", "")
                break
        if chunks:
            break
except Exception as e:
    probe = "error: " + type(e).__name__ + ": " + str(e)[:150]

paired = [
    {"index": i, "content": c, "embedding": embeddings[i]}
    for i, c in enumerate(chunks)
    if i < len(embeddings) and embeddings[i]
]
payload_json = json.dumps(paired)

# Emit one item per chunk. The Execute Query node runs per item, so each
# call carries a single embedding rather than the whole batch — the
# parameter field cannot handle a full-batch payload.
items = []
for i, c in enumerate(chunks):
    if i < len(embeddings) and embeddings[i]:
        items.append({
            "json": {
                "org_id": org_id,
                "brand_kit_id": brand_kit_id,
                "chunk_index": i,
                "content": c,
                "embedding_json": json.dumps(embeddings[i]),
            }
        })

if not items:
    items = [{"json": {
        "org_id": org_id,
        "brand_kit_id": brand_kit_id,
        "chunk_index": -1,
        "content": "",
        "embedding_json": "[]",
        "probe": probe,
    }}]

return items

